class EditCourseActions extends Component {
  constructor(props) {
    super(props);
    this.addLevel = this.addLevel.bind(this);

    this.state = {
      isLoading: false,
    };
  }

  addLevel(kind) {
    this.setState({isLoading: true});

    var pool_id = null;
    if (kind == 'things') {
      pool_id = this.props.course.last_pool_id;
    }
    var data = {
      course_id: this.props.course.id,
      pool_id: pool_id,
      kind: kind,
    };
    $.ajax({
      url: '/ajax/level/add',
      method: 'POST',
      data,
      headers: {
        'X-CSRFToken': window.MEMLIKE.course.csrftoken,
        'X-Referer': window.MEMLIKE.course.referer,
      },
      success: (data) => {
        this.props.onLevelAdded && this.props.onLevelAdded(data);
      },
      complete: () => {
        this.setState({isLoading: false});
      },
    });
  }

  render() {
    return (
      <div className="edit-course-actions clearfix">
        <div className="actions actions-right">
          {this.state.isLoading && <span className="loading-spinner left"></span>}

          <button type="button" className="btn" onClick={() => this.addLevel('multimedia')}>Add multimedia</button>
          <button type="button" className="btn green" onClick={() => this.addLevel('things')}>Add level</button>
        </div>
      </div>
    );
  }
}

class Edit extends Component {
  constructor(props) {
    super(props);
    this.setNewRow = this.setNewRow.bind(this);
    this.onLevelAdded = this.onLevelAdded.bind(this);
    this.state = {
      addedLevels: [],
    }
  }

  setNewRow(thingsRowTemplate) {
    this.thingsRowTemplate = thingsRowTemplate;

    bindEditEvents(thingsRowTemplate);
  }

  onLevelAdded(data) {
    if (!data.id) {
      return;
    }
    this.setState({
      addedLevels: [...this.state.addedLevels, {
        id: data.id,
        pool_id: data.pool_id,
        name: '',
      }],
    });
  }

  render() {
    var opentab = window.location.hash.match(/#(i|l)_(\d+)/);
    var c = 0;

    return <div>
      {this.props.course.last_pool_id && (
        <EditCourseActions course={this.props.course} onLevelAdded={this.onLevelAdded} />
      )}
      {this.props.course.levels.map((level, i) => {
        var show = false;
        if(opentab) {
          if(opentab[1] == 'i') {
            show = (i+1 == opentab[2]);
          } else {
            show = (level.id == opentab[2]);
          }
        }
        return c++, <EditLevel
          show={show}
          index={c}
          key={i}
          level={level}
          setNewRow={this.setNewRow}
          url={this.props.course['url'] + c}
          />;
      })}
      {this.state.addedLevels.map((level, i) => {
        return c++, <EditLevel
          show={true}
          index={c}
          key={'a_' + i}
          level={level}
          setNewRow={this.setNewRow}
          url={this.props.course['url'] + c}
          />;
      })}
    </div>;
  }
}

class EditLevel extends Component {
  constructor(props) {
    super(props);

    this.state = {
      show: false,
      isLoading: false,
      content: '',
    };
    this.toggle = this.toggle.bind(this);
  }

  componentDidMount() {
    if(this.props.show) {
      this.getData();
    }
  }

  toggle() {
    if(!this.state.show && !this.data) {
      this.getData();

    } else {
      this.setState({
        show: !this.state.show,
      });
    }
  }

  onGetDataSuccess(data) {
    var content = '';
    if(this.props.level.pool_id) {
      var $div = $('.table-container', data.rendered);
      content = $div.get(0).outerHTML;

      var newRowTemplate = $div.find('tr').last().get(0).outerHTML;
      this.props.setNewRow(newRowTemplate);

    } else {
      var $div = $('.multimedia-edit', data.rendered);

      $('*[id]', $div).attr('id', null);

      content = `<div class="multimedia-edit">
        <nav>
          <ul class="multimedia-preview__tabs">
            <li class="multimedia-preview__tab multimedia-preview__tab--edit active">Edit</li>
            <li class="multimedia-preview__tab multimedia-preview__tab--preview">Preview</li>
          </ul>
        </nav>
        <div class="multimedia-preview__content hide">
          <div class="multimedia-wrapper"></div>
        </div>` + $div.get(0).innerHTML + '</div>';

      this.props.setNewRow();
    }
    this.setState({
      show: true,
      content,
    });
  }

  onGetDataDone() {
    this.setState({
      isLoading: false,
    });
  }

  onGetDataError() {
    alert('Something went wrong');
  }

  getData() {
    this.setState({
      isLoading: true,
    });

    $.ajax({
      url: '/ajax/level/' + this.props.level.id,
      success: this.onGetDataSuccess.bind(this),
      error: this.onGetDataError.bind(this),
      complete: this.onGetDataDone.bind(this),
    });
  }

  render() {
    var level = this.props.level;

    return <div
      className={'edit-level nicebox' + (this.state.show ? '' : ' collapsed')}
      data-level-index={this.props.index}
      data-level-id={level.id}
      data-pool-id={level.pool_id || ''}
    >
      <div className="edit-level-actions">
        {this.state.isLoading && <span className="loading-spinner left"></span>}
        {this.state.show && (
          <div className="edit-level-actions-group">
            <div className="btn-group">
              <button className="delete-level btn action" title={window.I18N.delete_level}>
                <i class="ico ico-grey ico-trash"></i>
              </button>
            </div>

            <div className="btn-group">
              <button className="generate-audio btn action" title="">
                {window.I18N.generate_audio}
              </button>
            </div>

            <div className="btn-group">
              <label className="export-level btn action" title={window.I18N.export_level}>
                {window.I18N.export_level}
              </label>
              <label className="import-level btn action" title={window.I18N.import_level} htmlFor={'import_' + level.id}>
                <input type="file" id={'import_' + level.id} />
                {window.I18N.import_level}
              </label>
            </div>

            <div className="btn-group">
              <a class="btn action" href={this.props.url} title={window.I18N.goto_level}>
                {window.I18N.goto_level}
              </a>
            </div>
          </div>
        )}
        <label className="toggle action" onClick={this.toggle}>
          <span className="ico ico-grey ico-arr-down"></span>
        </label>
      </div>

      <div className="edit-level-label">
        <label>{level.name}</label>
        {!level.pool_id && <span>&nbsp;(multimedia)</span>}
      </div>

      {this.state.show && <div className="edit-level-content" dangerouslySetInnerHTML={{__html: this.state.content}}></div>}
    </div>;
  }
}

//+--------------------------------------------------------
//| Events
//+--------------------------------------------------------

var isInit  = false,
    focused = false,
    altInit = false,
    thingsRowTemplate = '';

function bindEditEvents(tpl) {
  if (tpl) {
    thingsRowTemplate = tpl;
  }
  if(isInit) {
    return;
  }
  isInit = true;
  init();

  function init() {
    $('#edit-levels')

    // New row
    .on('focus', 'input', focus_input)
    .on('blur', '.adding input.wide', blur_input_adding)
    .on('focus', '.adding tr:last-child input.wide', focus_lastRow)

    // Update cell
    .on('click', 'div.text', click_cell)
    .on('keyup', 'input.wide', type_cell)
    .on('blur', '.things input.wide', blur_input_thing)

    .on('click', '.multimedia-edit button', click_saveMultimedia)

    // Preview multimedia
    .on('click', 'li.multimedia-preview__tab', click_multimediaPreviewToggle)

    // Update alternatives
    .on('click', '.edit-alts', click_editAlt)

    // Update attachments
    .on('change', '.things input[type="file"]', send_file)
    .on('click', '.dropdown-toggle', click_displayFiles)
    .on('click', '.dropdown-row .ico-trash', click_removeFile)
    .on('click', '.audio-player', click_audio)

    // Delete row
    .on('click', '.ico-close', click_deleteRow)

    // Import/export
    .on('click', '.export-level', click_exportLevel)
    .on('change', '.import-level input', send_importLevel)
    .on('click', '.generate-audio', AudioUploader.click_generateAudio)

    // Delete level
    .on('click', '.delete-level', click_deleteLevel);
  }

  //+---------------------------------------------------------------------------
  // Remember current input focused
  function focus_input() {
    focused = this;
  }

  //+---------------------------------------------------------------------------
  // On blur cell in adding tbody: add row
  function blur_input_adding() {
    focused = false;

    // Retrieve the row datas
    var $tr  = $(this).closest('tr'),
        data = {},
        empty = true;

    $tr.find('td[data-key]').each(function(){
      var val = $(this).find('input').val();
      if(val) {
        empty = false;
      }
      data[$(this).data('key')] = val;
    });
    if(empty) {
      return;
    }

    // Check if we changed row or just cell of the row
    setTimeout(function(){
      if(focused && $(focused).closest('tr').is($tr)) {
        return;
      }
      $tr.addClass('disabled');
      addRow($tr, data);
    }, 100);
  }

  // POST new row
  function addRow($tr, data, callback){
    var $level  = $tr.closest('.edit-level'),
        levelId = $level.data('level-id');

    $.ajax({
      url: '/ajax/level/' + levelId + '/add',
      method: 'POST',
      data: {
        csrftoken: window.MEMLIKE.course.csrftoken,
        referer: window.MEMLIKE.course.referer,
        data: JSON.stringify(data)
      },
      success: function(json){
        var html   = json.rendered_thing,
            $newTr = $(html).appendTo($('.things', $level));

        $tr.remove();
        callback && callback('success', levelId, $newTr);
      },
      error: function(xhr){
        alert('Something went wrong');

        console.error(xhr);
        $tr.removeClass('disabled');
        callback && callback('error', levelId, $tr);
      },
    });
  }

  // Import rows: handle file upload from URL
  async function downloadFromUrls($tr, levelId, uploads) {
    var thingId = $tr.data('thing-id');

    for(var i=0; i<uploads.length; i++) {
      var upload  = uploads[i],
          cellId  = upload[0],
          $column = $tr.children('[data-key="' + cellId + '"]');

      await downloadFromUrl($column, thingId, cellId, upload);
    }
  }
  function downloadFromUrl($column, thingId, cellId, upload) {
    var name    = upload[1],
        url     = upload[2],
        mime    = upload[3];

    return fetch(url).then(res => res.blob()).then(blob => {
      var file = new File([blob], name, {type: mime});

      return new Promise((resolve, reject) => {
        uploadFile($column, cellId, thingId, file, resolve, reject);
      });
    });
  }

  //+---------------------------------------------------------------------------
  // Focus last row: add a new row
  function focus_lastRow(){
    $(this).closest('.adding').append(thingsRowTemplate);
  }

  //+---------------------------------------------------------------------------
  // Click on cell: display input
  function click_cell() {
    if(this.firstElementChild) {
      return;
    }
    var input       = document.createElement('input');
    input.value     = this.innerHTML;
    input.type      = 'text';
    input.className = 'wide';
    this.appendChild(input);
    input.focus();
  }

  //+---------------------------------------------------------------------------
  // On enter: focus next row
  function type_cell(e){
    if(e.which != 13) {
      return;
    }
    var $tr     = $(e.target).closest('tr'),
        $nextTr = $tr.next('tr');

    if($nextTr.length == 0) {
      $nextTr = $tr.closest('tbody').next('tbody').children(':not(.header)').first();
      $nextTr.find('input.wide').first().focus();
    } else {
      $nextTr.find('div.text, input.wide').first().trigger('click').focus();
    }
  }

  //+---------------------------------------------------------------------------
  // On click "alternatives": edit alternatives
  function click_editAlt(e) {
    e.preventDefault();

    var $btn    = $(e.target),
        thingId = $btn.closest('.thing').data('thing-id'),
        cellId  = $btn.closest('.column').data('key');

    $.ajax({
      url: '/ajax/level/' + thingId + '/alt',
      method: 'POST',
      data: {
        csrftoken: window.MEMLIKE.course.csrftoken,
        referer: window.MEMLIKE.course.referer
      },
      success: function(data) {
        var alts = data.thing.columns[cellId].alts,
            html = `<div class="alts">
              ${alts.map((alt) => `<div class="alt">
                <input type="text" name="${alt.id}" value="${alt.val}" />
                <button type="button" class="alt-action"></button>
              </div>`).join('')}

              <div class="alt">
                <input type="text" value="" />
                <button type="button" class="alt-action"></button>
              </div>
            </div>

            <div class="alt-actions">
              <button class="btn alt-cancel">Annuler</button>
              <button class="btn active alt-save" data-cell="${cellId}" data-thing=${thingId}>Sauvegarder</button>
            </div>`;

        window.modal.open(html);
        bindAltEvents();
      }
    });
  }

  function bindAltEvents() {
    if(altInit) {
      return;
    }
    altInit = true;

    $('#modal')
    .on('click', '.alt-cancel', function(){ window.modal.close(); })
    .on('click', '.alt-action', click_altAction)
    .on('click', '.alt-save', click_altSave);
  }

  // Click alt action: last row = add new, others = remove current
  function click_altAction() {
    var $alt  = $(this).closest('.alt'),
        $alts = $(this).closest('.alts');

    if($alts.children().last().is($alt)) {
      $alts.append(`<div class="alt">
        <input type="text" value="" />
        <button type="button" class="alt-action"></button>
      </div>`);
    } else {
      $alt.remove();
    }
  }

  // Click alt save: save modal content and close
  function click_altSave() {
    var cellId  = $(this).data('cell'),
        thingId = $(this).data('thing'),
        alts    = [];

    $('#modal input').each(function(){
      if(this.value.trim()) {
        alts.push(this.value.trim());
      }
    });

    $.ajax({
      url: '/ajax/level/' + thingId + '/alt_edit',
      method: 'POST',
      data: {
        csrftoken: window.MEMLIKE.course.csrftoken,
        referer: window.MEMLIKE.course.referer,
        alts: JSON.stringify(alts),
        cell_id: cellId,
      },
      success: function() {
        window.modal.close();
      }
    });
  }

  //+---------------------------------------------------------------------------
  // On click "delete": delete row
  function click_deleteRow(e){
    e.preventDefault();
    if(confirm(window.I18N.confirm_del_row)) {
      removeRow($(e.target).closest('tr'));
    }
  }

  function removeRow($tr){
    var $level  = $tr.closest('.edit-level'),
        thingid = $tr.data('thing-id'),
        levelid = $level.data('level-id');

    $.ajax({
      url: '/ajax/level/' + levelid + '/remove',
      method: 'POST',
      data: {
        csrftoken: window.MEMLIKE.course.csrftoken,
        referer: window.MEMLIKE.course.referer,
        id_thing: thingid
      },
      success: function(){
        $tr.remove();
      },
      error: function(xhr){
        console.error(xhr);
        $tr.remove('disabled');
      }
    });
  }

  //+---------------------------------------------------------------------------
  // On blur cell in things tbody: update cell
  function blur_input_thing(){
    var txt  = this.value.trim(),
        $div = $(this.parentNode);

    if(txt == $div.text()) {
      $div.text(txt);
      return;
    }
    $div.text(txt);

    var thingId = $div.closest('.thing').data('thing-id'),
        cellId  = $div.closest('.column').data('key');

    updateCell(thingId, cellId, txt);
  }

  // POST new cell value
  function updateCell(thingId, cellId, txt) {
    $.ajax({
      url: '/ajax/level/' + thingId + '/edit',
      method: 'POST',
      data: {
        csrftoken: window.MEMLIKE.course.csrftoken,
        referer: window.MEMLIKE.course.referer,
        cell_id: cellId,
        cell_value: txt,
      },
      error: function(){
        alert('Something went wrong when trying to update cell');
      }
    });
  }

  //+---------------------------------------------------------------------------
  // On send file: upload file
  function send_file(){
    var $column = $(this).closest('.column'),
        cellId  = $column.data('key'),
        thingId = $(this).closest('.thing').data('thing-id'),
        file    = this.files[0];

    uploadFile($column, cellId, thingId, file);
  }

  function uploadFile($column, cellId, thingId, file, resolve=null, reject=null) {
    var fd = new FormData();
    fd.append('file', file);
    fd.append('csrftoken', window.MEMLIKE.course.csrftoken);
    fd.append('referer', window.MEMLIKE.course.referer);
    fd.append('cell_id', cellId);

    $.ajax({
      url: '/ajax/level/' + thingId + '/upload',
      data: fd,
      processData: false,
      contentType: false,
      type: 'POST',
      success: function(data){
        if(data.message) {
          alert(data.message);
        }
        $column.replaceWith(data.rendered);
        resolve && resolve($column);
      },
      error: function(){
        reject && reject($column);
      },
    });
  }

  //+---------------------------------------------------------------------------
  // On click files: display attachments
  function click_displayFiles(e) {
    var div = e.target.nextElementSibling;
    div.innerHTML = div.innerHTML.replace(/ src="#"/g, '')
                                 .replace(/ data-url="/g, ' src="');
  }

  // On click dropdown content
  function click_audio(e) {
    e.preventDefault();
    e.stopPropagation();

    window.audioPlayer && window.audioPlayer.play.call(e.target, e);
  }

  //+---------------------------------------------------------------------------
  // On click remove file: remove attachment
  function click_removeFile(e){
    e.preventDefault();
    e.stopPropagation();

    if(!confirm(window.I18N.confirm_del_file)) {
      return;
    }
    removeFile($(e.target));
  }

  function removeFile($btn) {
    var fileId  = $btn.closest('.dropdown-row').data('file-id'),
        $column = $btn.closest('.column'),
        cellId  = $column.data('key'),
        thingId = $btn.closest('.thing').data('thing-id');

    $.ajax({
      url: '/ajax/level/' + thingId + '/upload_remove',
      data: {
        'csrftoken': window.MEMLIKE.course.csrftoken,
        'referer': window.MEMLIKE.course.referer,
        'cell_id': cellId,
        'file_id': fileId,
      },
      type: 'POST',
      success: function(data){
        if(data.message) {
          alert(data.message);
        }
        $column.replaceWith(data.rendered);
      }
    });
  }

  //+---------------------------------------------------------------------------
  // On click save: update multimedia content
  function click_saveMultimedia() {
    var $btn = $(this);
    $btn.attr('disabled', 'disabled').addClass('loading-spinner-after');

    var $level = $btn.closest('.edit-level');
    var levelId = $level.data('level-id');
    $.ajax({
      url: '/ajax/level/' + levelId + '/edit_multimedia',
      method: 'POST',
      data: {
        csrftoken: window.MEMLIKE.course.csrftoken,
        referer: window.MEMLIKE.course.referer,
        txt: $btn.prev().val(),
        course_id: window.MEMLIKE.course.id,
        level_index: $level.data('level-index'),
      },
      error: function() {
        alert('Something went wrong when trying to update the content');
      },
      complete: function(){
        $btn.removeAttr('disabled').removeClass('loading-spinner-after');
      }
    });
  }

  function click_multimediaPreviewToggle(e) {

    // Toggle current tab
    var $btn       = $(e.target),
        isPreview  = $btn.hasClass('multimedia-preview__tab--preview');

    $btn.addClass('active')
        .siblings()
        .removeClass('active');

    // Show/hide preview
    var $container = $btn.closest('.multimedia-edit'),
        $textarea  = $('textarea', $container),
        $preview   = $('.multimedia-preview__content', $container);

    if(isPreview) {
      var html = window.markdown.decode($textarea.val());

      $preview.children(':first').html(html);
      $preview.removeClass('hide');
      $textarea.addClass('hide');
    } else {
      $preview.addClass('hide');
      $textarea.removeClass('hide');
    }
  }

  //+---------------------------------------------------------------------------
  function click_deleteLevel() {
    if(!confirm(window.I18N.confirm_del_level)) {
      return;
    }

    var $btn = $(this);
    $btn.attr('disabled', 'disabled').addClass('loading-spinner loading-spinner-m');

    var $level = $btn.closest('.edit-level');
    var levelId = $level.data('level-id');

    $.ajax({
      url: '/ajax/level/delete',
      method: 'POST',
      data: {
        course_id: window.MEMLIKE.course.id,
        level_id: levelId,
      },
      headers: {
        'X-CSRFToken': window.MEMLIKE.course.csrftoken,
        'X-Referer': window.MEMLIKE.course.referer,
      },
      error: function() {
        alert('Something went wrong when trying to delete the level');
      },
      success: function() {
        $level.addClass('hide');
      },
      complete: function(){
        $btn.removeAttr('disabled').removeClass('loading-spinner loading-spinner-m');
      }
    });
  }

  //+---------------------------------------------------------------------------
  // Import/export
  function click_exportLevel() {
    var $level     = $(this).closest('.edit-level'),
        levelId    = $level.data('level-id'),
        $table     = $level.find('table'),
        csvContent = export_things($table);

    download(csvContent, window.MEMLIKE.course.title + '_' + levelId + '.csv', 'text/csv;encoding:utf-8');
  }

  function export_things($table) {
    var row        = [],
        csvContent = '';

    // Get headers
    $table.children('.columns').find('.column,.attribute').each(function(){
      row.push($(this).text().trim());
    });
    csvContent += exportCsv(row);

    // Get rows
    $table.children('.things').children().each(function(){
      var empty = true;

      row = [];

      // Get columns
      $(this).children('.column,.attribute').each(function(){
        var $col = $(this),
            txt  = '';

        // Text
        if($col.hasClass('text')) {
          txt = $col.find('.text').text().trim();

        // Image attachment
        } else if($col.hasClass('image')) {
          var list = [];

          // Get list of images
          $col.find('.images').children('.dropdown-row').each(function(){
            var $item = $(this).find('img'),
                url   = $item.attr('data-url');

            if(!url) {
              url = $item.attr('src');
            }
            if(url && url != '#') {
              var filename = url.substring(url.lastIndexOf('/')+1);
              list.push(filename + ' (' + url + ')');
            }
          });
          txt = list.join(',');

        } else if($col.hasClass('audio')) {
          var list = [];

          // Get list of audios
          $col.find('.audios').children('.dropdown-row').each(function(){
            var $item = $(this).find('a'),
                url   = $item.attr('data-url');

            if(!url) {
              url = $item.attr('src');
            }
            if(url && url != '#') {
              var filename = url.substring(url.lastIndexOf('/')+1);
              list.push(filename + ' (' + url + ')');
            }
          });
          txt = list.join(',');
        }

        // Add column to row
        if(txt) {
          empty = false;
        }
        row.push(txt);
      });

      // Export row
      if(!empty) {
        csvContent += exportCsv(row);
      }
    });
    return csvContent;
  }

  function send_importLevel(e) {
    if(!e.target.files) {
      return;
    }
    var file = e.target.files[0];
    if(file.type != 'text/csv') {
      alert(window.I18N.import_err_ext);
      return;
    }

    var reader = new FileReader(),
        $level = $(this).closest('.edit-level');
    reader.onload = (function(f) {
      return function(e) {
        import_file($level, e.target.result);
      };
    })(file);

    reader.readAsText(file);
  }

  function import_file($level, content) {
    var data = $.csv.toArrays(content);
    if(!data.length) {
      return;
    }

    var $table        = $level.find('table'),
        $adding       = $table.children('.adding'),
        table_headers = [],
        table_keys    = [],
        types         = [];

    // Get table headers
    $table.children('.columns').find('.column,.attribute').each(function(){
      var $col = $(this),
          type = 'text';

      if($col.hasClass('image')) {
        type = 'image';
      } else if($col.hasClass('audio')) {
        type = 'audio';
      }
      types.push(type);

      table_headers.push($col.text().trim().toLowerCase());
      table_keys.push($col.data('key'));
    });

    // Get position of headers in CSV
    var headers = [],
        empty   = true;
    for(var i=0; i<data[0].length; i++) {
      var header = data[0][i].trim(),
          k      = table_headers.indexOf(header.toLowerCase());

      if(k==-1) {
        headers.push(0);
      } else {
        empty = false;
        headers.push({key: table_keys[k], type: types[k], txt: header});
      }
    }
    table_headers = null;
    table_keys    = null;
    types         = null;

    // Format rows
    var rows = [];

    if(!empty) {
      for(var i=1; i<data.length; i++) {
        var row        = data[i],
            row_import = {},
            row_upload = [];

        // Get row content in the right order
        for(var j=0; j<row.length; j++) {
          if(!headers[j]) {
            continue;
          }
          var txt = row[j].trim();
          if(!txt) {
            continue;
          }

          // Add its value
          var cellId = headers[j].key,
              type   = headers[j].type;

          if(type == 'text') {
            row_import[cellId] = txt;

          // Upload its attachments once added
          } else {
            var list = txt.split(',');
            for(var l=0; l<list.length; l++) {
              var item = list[l];

              // 184839286_180428_1821_37.jpg (https://static.memrise.com/uploads/things/images/184839286_180428_1821_37.jpg)
              var match = item.match(/^([^(]+)\(([^)]+)\)$/),
                  filename = null,
                  url = null;

              if (match) {
                filename = match[1].trim();
                url = match[2].trim();
              } else {

                // https://static.memrise.com/uploads/things/images/184839286_180428_1821_37.jpg
                match = item.match(/^https?:\/\/[^)]+\/[^.]+(\/[_a-zA-Z0.9]+\.[a-zA-Z0.9]+)$/);
                if (match) {
                  url = item;
                  filename = match[1].trim();
                }
              }

              if (!url || !filename) {
                continue;
              }
              var filename = match[1].trim(),
                  mime     = '',
                  ext      = filename.substring(filename.lastIndexOf('.')+1);

              switch(ext) {
                case 'png':  mime = 'image/png'; break;
                case 'jpg':  mime = 'image/jpeg'; break;
                case 'jpeg': mime = 'image/jpeg'; break;
                case 'gif':  mime = 'image/gif'; break;
                case 'mp3':  mime = 'audio/mpeg'; break;
                case 'mp4':  mime = 'video/mp4'; break;
                case 'aac':  mime = 'audio/aac'; break;
              }
              if(!mime) {
                continue;
              }
              row_upload.push([cellId, filename, match[2].trim(), mime]);
            }
          }
        }

        // Create a new table row
        rows.push({data: row_import, upload: row_upload});
      }
    }
    data = null;

    import_preview(rows, empty ? false : headers, $adding);
  }

  function import_preview(rows, headers, $adding) {
    if(!headers) {
      alert(window.I18N.import_err_empty);
      return;
    }
    var html = '<div class="import_preview">';
    html += '<button class="btn active run_import top">' + window.I18N.import_level + '</button>';
    html += '<table>';

    // Display headers
    html += '<thead><tr>';
    for(var i=0; i<headers.length; i++) {
        if(!headers[i]) {
          continue;
        }
      html += '<th>' + headers[i].txt + '</th>';
    }
    html += '</tr></thead>';

    // Display rows
    html += '<tbody>';
    for(var i=0; i<rows.length; i++) {
      html += '<tr>';

      var row  = rows[i],
          data = Object.assign({}, row.data);

      // Bring back upload to data
      for(var j=0; j<row.upload.length; j++) {
        var upload  = row.upload[j],
            cellId  = upload[0],
            url     = upload[2];

        if(typeof data[cellId] != 'undefined') {
          data[cellId].push(url);
        } else {
          data[cellId] = [url];
        }
      }

      // Display data
      for(var j=0; j<headers.length; j++) {
        if(!headers[j]) {
          continue;
        }
        var k       = headers[j].key,
            type    = headers[j].type,
            content = data[k] || '';

        if(type == 'image') {
          content = content.map(function(txt){
            return '<img src="' + txt + '">';
          }).join('');

        } else if(type == 'audio') {
          content = content.map(function(txt){
            return '<audio src="' + txt + '">';
          }).join('');
        }
        html += '<td>' + content + '</td>';
      }
      html += '</tr>';
    }
    html += '</tbody></table>';
    html += '<button class="btn active run_import bottom">' + window.I18N.import_level + '</button>';
    html += '</div>';
    window.modal.open(html);

    // Close modal = cancel (clear out data)
    window.modal.onclose('import', function(){
      rows    = null;
      headers = null;
      $adding = null;

      this.onclose('import', null);
    });

    var run_import = false;

    $('.run_import', window.modal.container).one('click', function(){
      if(run_import) {
        return;
      }
      run_import = true;

      window.modal.onclose('import', null);
      window.modal.close();

      while (rows.length) {
        let batch = rows.splice(0, 10);

        setTimeout(function(){
          import_rows(batch, $adding);
        }, 0);
      }
      rows    = null;
      headers = null;
    });
  }

  /**
   * List of rows that have been imported,
   * that do have an upload to handle
   */
  function imported_rows(rows) {
    if (!window.File) {
      return;
    }
    for(var i=0; i<rows.length; i++) {
      var row = rows[i],
          uploads = row.upload;

      downloadFromUrls(row.$tr, row.levelId, row.upload);
    }
  }

  function import_rows(rows, $adding) {
    var pending = 0;
    var callbackRows = [];

    var addCallback = function(data, upload) {
      pending++;

      return function(status, levelId, $newTr) {
        pending--;
        if (status == 'success') {
          callbackRows.push({data, upload, levelId, $tr: $newTr});
        }
        if(pending == 0) {
          setTimeout(function() {
            imported_rows(callbackRows);
          }, 0);
        }
      };
    };

    for(var i=0; i<rows.length; i++) {
      var data   = rows[i].data,
          upload = rows[i].upload,
          $tr    = $(thingsRowTemplate).appendTo($adding).prev().addClass('disabled');

      for(var k in data) {
        $tr.children('[data-key="' + k + '"]').find('input').val(data[k]);
      }
      var callback = upload ? addCallback(data, upload) : false;
      addRow($tr, data, callback);
    }
  }
}

/**
 * @param array row
 * @return string
 */
function exportCsv(row) {
  var txt = '';

  for(var i=0; i<row.length; i++) {
    if(i > 0) {
      txt += ',';
    }
    if(row[i].indexOf(',') == -1) {
      txt += row[i];
    } else {
      txt += '"' + row[i].replace(/\\/g, '\\\\').replace(/"/g, '"') + '"';
    }
  }
  return txt + '\n';
}

/**
 * Trigger a file download of the given mimeType
 * ex: download(csvContent, 'dowload.csv', 'text/csv;encoding:utf-8');
 *
 * @param string content
 * @param string fileName
 * @param mimeType
 */
var download = function(content, fileName, mimeType) {
  var a = document.createElement('a');
  mimeType = mimeType || 'application/octet-stream';

  // IE10
  if(navigator.msSaveBlob) {
    navigator.msSaveBlob(new Blob([content], {
      type: mimeType
    }), fileName);

  //html5 A[download]
  } else if (URL && 'download' in a) {
    a.href = URL.createObjectURL(new Blob([content], {
      type: mimeType
    }));
    a.setAttribute('download', fileName);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);

  } else {
    window.location.href = 'data:application/octet-stream,' + encodeURIComponent(content); // only this mime type is supported
  }
};

